package io.imiocode.team.tool;
import com.fasterxml.jackson.databind.node.ObjectNode;import io.imiocode.team.model.TeamPrincipal;import io.imiocode.team.task.TeamTaskService;import io.imiocode.tool.*;import java.util.function.Supplier;
public final class TaskCreateTool extends AbstractTaskTool {public TaskCreateTool(TeamTaskService t,Supplier<TeamPrincipal> p,ToolLimits l,SecretRedactor r){super(def(),t,p,l,r);}private static ToolDefinition def(){ObjectNode s=schema();var p=s.withObject("properties");p.putObject("title").put("type","string");p.putObject("description").put("type","string");p.putObject("assignee").put("type","string");s.putArray("required").add("title");return new ToolDefinition("TaskCreate","在当前团队创建持久任务。",s,ToolRisk.LOW);}@Override protected ToolResult executeValidated(ObjectNode a){rejectUnknownFields(a,"title","description","assignee");return json(tasks.create(principal(),requireText(a,"title"),a.path("description").asText(""),a.path("assignee").asText("")));}}
